<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {Search,Plus,Trash2,Pencil,RotateCcw,ChevronLeft,ChevronRight,Download,Database,SlidersHorizontal,FileClock,Eye,Check,X,Calculator} from 'lucide-vue-next'
import {calculateBmi} from '../bodyMetrics'
import {recordName,recordCostLabel} from '../productPricing'
import RecalculateDialog from './RecalculateDialog.vue'
import LifeJournal from './LifeJournal.vue'
import {api,state,deleteRow,restoreRow,refresh} from '../api'
import type {Row,Field} from '../types'
import {collectionLabels,shortDate,money,number} from '../types'
const props=defineProps<{collection?:string;manager?:boolean;refreshKey?:number}>();const emit=defineEmits<{edit:[collection:string,row?:Row,preset?:Record<string,any>];changed:[];notify:[message:string]}>()
const selectedCollection=ref(props.collection||'smoking'),search=ref(''),page=ref(1),trash=ref(false),trashRows=ref<Row[]>([]),error=ref(''),busy=ref(false),selected=ref<string[]>([]),confirmDelete=ref<Row[]|null>(null),inspecting=ref<Row|null>(null),audit=ref<any[]|null>(null)
watch(()=>props.collection,v=>{if(v)selectedCollection.value=v})
const recalcRow=ref<Row|null>(null)
const pagedCollection=computed(()=>['journal','tasks'].includes(selectedCollection.value))
const derivedFields:Record<string,Field>={bmi:{key:'bmi',label:'BMI',type:'number'},actualMl:{key:'actualMl',label:'本人饮用 ml',type:'number'},snapshotAbv:{key:'snapshotAbv',label:'当时酒精度 %',type:'number'},ethanolEquivalent42Ml:{key:'ethanolEquivalent42Ml',label:'折合42°白酒 ml',type:'number'}}
const hasAlcoholLink=computed(()=>!trash.value&&['smoking','intimacy'].includes(selectedCollection.value))
function alcoholLink(row:Row){return (selectedCollection.value==='smoking'?state.analytics.smokingLinks:state.analytics.links)?.[row.id]}
function alcoholLinkLabel(row:Row){const link=alcoholLink(row);if(!link)return '待判断';if(link.source==='MANUAL')return link.effective==='YES'?'本人确认酒后':link.effective==='NO'?'本人确认非酒后':'本人不确定';return ({DURING_DRINKING:'饮酒期间',POSSIBLE_AFTER_DRINKING:'估算酒后',RECENT_RECORDED_DRINKING:'近期有饮酒',NO_RECORDED_RECENT_DRINKING:'未找到饮酒记录',INSUFFICIENT_DATA:'信息不足'} as Record<string,string>)[link.status]||'待判断'}
const schema=computed(()=>state.schema.find(s=>s.name===selectedCollection.value)),rows=computed(()=>trash.value?trashRows.value:state.collections[selectedCollection.value]||[])
const filtered=computed(()=>rows.value.filter(r=>JSON.stringify(r).toLocaleLowerCase().includes(search.value.toLocaleLowerCase())).sort((a,b)=>String(b.occurredAt||b.startedAt||b.measuredAt||b.createdAt).localeCompare(String(a.occurredAt||a.startedAt||a.measuredAt||a.createdAt))))
const displayFields=computed(()=>{const priorities:Record<string,string[]>={smoking:['occurredAt','productId','count','source','mood'],sessions:['startedAt','endedAt','context','notes'],drinks:['occurredAt','productId','actualMl','snapshotAbv','ethanolEquivalent42Ml'],intimacy:['occurredAt','count','moodBefore','moodAfter','manualAlcohol'],purchases:['occurredAt','productId','quantity','amount','payer'],prices:['productId','amount','priceType','effectiveDate','channel'],products:['kind','brand','name','variant','packagePrice','priceConfirmed'],body:['measuredAt','heightCm','weightKg','bodyFatPct','bmi','waistCm'],health:['title','topic','sourceUrl','reviewedAt']};const keys=priorities[selectedCollection.value];return keys?keys.map(k=>schema.value?.fields.find(f=>f.key===k)||derivedFields[k]).filter(Boolean) as Field[]:schema.value?.fields.slice(0,6)||[]})
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/12))),visible=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12))
watch([selectedCollection,trash],async()=>{page.value=1;selected.value=[];error.value='';if(pagedCollection.value){trash.value=false;trashRows.value=[];return}if(trash.value){try{trashRows.value=await api<Row[]>(`/data/${selectedCollection.value}?deleted=true`)}catch(e){error.value=(e as Error).message}}})
watch(search,()=>page.value=1)
function display(r:Row,f:Field){const v=f.key==='bmi'?calculateBmi(r):f.key==='ethanolEquivalent42Ml'?(r.ethanolEquivalent42Ml??(r.ethanolGrams==null?null:Number(r.ethanolGrams)/0.33138)):r[f.key];if(f.type==='product'){if(v==null||v==='')return '待选种类';return recordName(r.snapshotName||state.collections.products?.find(p=>p.id===v)?.name,'已停用商品')}if(v==null||v==='')return '—';if(f.type==='session')return String(state.collections.sessions?.find(s=>s.id===v)?.startedAt||v).replace('T',' ').slice(0,16);if(f.type==='boolean')return v?'是':'否';if(f.type==='select')return f.options?.find(o=>o.value===v)?.label||v;if(f.type==='datetime')return String(v).replace('T',' ').slice(0,16);if(f.type==='date')return shortDate(v);if(['amount','unitPrice','packagePrice'].includes(f.key))return money(v);if(derivedFields[f.key])return number(v,1);return v}
function toggleAll(){selected.value=selected.value.length===visible.value.length?[]:visible.value.map(r=>r.id)}
async function remove(){if(!confirmDelete.value)return;busy.value=true;error.value='';try{for(const r of confirmDelete.value)await deleteRow(selectedCollection.value,r);await refresh();selected.value=[];confirmDelete.value=null;emit('changed');emit('notify','已移入回收站，可以随时恢复。')}catch(e){error.value=(e as Error).message;await refresh().catch(()=>{})}finally{busy.value=false}}
async function restore(r:Row){busy.value=true;try{await restoreRow(selectedCollection.value,r);trashRows.value=await api<Row[]>(`/data/${selectedCollection.value}?deleted=true`);await refresh();emit('changed');emit('notify','记录已恢复。')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function exportRows(){const fields=schema.value?.fields||[];const quote=(x:any)=>'"'+String(x??'').replaceAll('"','""')+'"';const csv='\ufeff'+[fields.map(f=>quote(f.label)).join(','),...filtered.value.map(r=>fields.map(f=>quote(display(r,f))).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`自记-${collectionLabels[selectedCollection.value]}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}
async function showAudit(){try{const result=await api<any>('/audit');audit.value=Array.isArray(result)?result:result.rows||result.items||[]}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="data-page"><div v-if="manager" class="collection-tabs"><button v-for="s in state.schema" :key="s.name" :class="{active:selectedCollection===s.name}" @click="selectedCollection=s.name">{{s.label||collectionLabels[s.name]}}<span v-if="!['journal','tasks'].includes(s.name)">{{state.collections[s.name]?.length||0}}</span></button></div><template v-if="pagedCollection"><button v-if="manager" class="text-link" style="margin-bottom:10px" @click="showAudit"><FileClock :size="15"/>查看操作历史</button><LifeJournal :key="selectedCollection" :initial-collection="selectedCollection==='tasks'?'tasks':'journal'" :refresh-key="refreshKey" management/></template><p v-if="selectedCollection==='prices'" class="hint">这里保存价格历史与参考资料，不会替换商品当前采用的单价。现行计价请到“商品资料 → 设置单价”中设置并确认。</p><section v-if="!pagedCollection" class="panel table-panel"><header class="table-heading"><div><span class="eyebrow">{{trash?'RECYCLE BIN':'YOUR LOCAL RECORDS'}}</span><h3>{{trash?'回收站':schema?.label||collectionLabels[selectedCollection]}} <span class="count-badge">{{filtered.length}}</span></h3></div><div class="toolbar"><button class="button secondary compact-button" @click="exportRows"><Download :size="15"/>导出</button><button v-if="manager" class="icon-button" title="操作历史" @click="showAudit"><FileClock :size="18"/></button><button class="button primary compact-button" @click="emit('edit',selectedCollection)"><Plus :size="16"/>新增</button></div></header><div class="table-filters"><label class="search-box"><Search :size="17"/><input v-model="search" placeholder="搜索品牌、时间、备注…"/></label><button class="filter-toggle" :class="{active:trash}" @click="trash=!trash"><RotateCcw :size="15"/>{{trash?'返回当前数据':'回收站'}}</button><button v-if="selected.length&&!trash" class="button danger compact-button" @click="confirmDelete=rows.filter(r=>selected.includes(r.id))"><Trash2 :size="15"/>删除 {{selected.length}} 条</button></div><p v-if="error" class="error-box" role="alert">{{error}}</p><div class="table-scroll"><table><thead><tr><th class="checkbox-cell"><input type="checkbox" aria-label="选择本页全部" :checked="selected.length===visible.length&&visible.length>0" @change="toggleAll"/></th><th v-for="f in displayFields" :key="f.key">{{f.label}}</th><th v-if="['smoking','drinks'].includes(selectedCollection)">按用量费用</th><th v-if="hasAlcoholLink">饮酒关联</th><th class="actions-cell">操作</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td class="checkbox-cell"><input type="checkbox" :aria-label="`选择记录 ${r.id}`" v-model="selected" :value="r.id"/></td><td v-for="f in displayFields" :key="f.key" class="sensitive" :title="String(display(r,f))"><span v-if="f.type==='boolean'" class="tag" :class="{mint:r[f.key]}">{{display(r,f)}}</span><span v-else>{{display(r,f)}}</span></td><td v-if="['smoking','drinks'].includes(selectedCollection)" class="sensitive">{{recordCostLabel(r,selectedCollection)}}<small v-if="r.costType==='REFERENCE'" class="muted"> 估算</small></td><td v-if="hasAlcoholLink" class="sensitive"><span class="tag" :class="{intimacy:alcoholLink(r)?.effective==='YES'}" :title="alcoholLink(r)?.reason||'尚未计算'">{{alcoholLinkLabel(r)}}</span></td><td class="actions-cell"><button class="icon-button" title="查看完整数据" @click="inspecting=r"><Eye :size="16"/></button><template v-if="!trash"><button v-if="['products','prices','purchases'].includes(selectedCollection)" class="icon-button" title="预览历史重算" @click="recalcRow=r"><Calculator :size="15"/></button><button class="icon-button" title="编辑" @click="emit('edit',selectedCollection,r)"><Pencil :size="15"/></button><button class="icon-button" title="移入回收站" @click="confirmDelete=[r]"><Trash2 :size="15"/></button></template><button v-else class="icon-button" title="恢复" :disabled="busy" @click="restore(r)"><RotateCcw :size="16"/></button></td></tr></tbody></table><div v-if="!visible.length" class="empty-state"><Database :size="34"/><strong>{{search?'没有匹配的记录':trash?'回收站是空的':'这里还没有记录'}}</strong><p>{{search?'换一个关键词试试。':'新建的真实数据会保存在这里，随时可以查看和修改。'}}</p><button v-if="!search&&!trash" class="button secondary" @click="emit('edit',selectedCollection)"><Plus :size="15"/>新增第一条</button></div></div><footer class="table-footer"><span>共 {{filtered.length}} 条 · 每页 12 条</span><div><button class="icon-button" title="上一页" :disabled="page<=1" @click="page--"><ChevronLeft :size="17"/></button><span>{{page}} / {{pages}}</span><button class="icon-button" title="下一页" :disabled="page>=pages" @click="page++"><ChevronRight :size="17"/></button></div></footer></section><p v-if="!pagedCollection" class="page-note">修改会保留操作历史。移入回收站的记录不再参与当前统计。</p>
<div v-if="confirmDelete" class="overlay centered" @click.self="confirmDelete=null"><section class="modal"><header><span class="icon-tile danger"><Trash2 :size="22"/></span><button class="icon-button" @click="confirmDelete=null" title="关闭"><X :size="20"/></button></header><h2>将 {{confirmDelete.length}} 条记录移入回收站？</h2><p>相关费用与统计会更新。你可以从回收站恢复；有其他数据引用时，系统会说明处理方式。</p><p v-if="error" class="error-box">{{error}}</p><footer><button class="button secondary" @click="confirmDelete=null">保留记录</button><button class="button danger" :disabled="busy" @click="remove">{{busy?'正在处理':'移入回收站'}}</button></footer></section></div>
<div v-if="inspecting||audit" class="overlay" @click.self="inspecting=null;audit=null"><section class="drawer"><header class="drawer-header"><div><small>RECORD DETAIL</small><h2>{{audit?'操作历史':'完整数据与计算依据'}}</h2></div><button class="icon-button" @click="inspecting=null;audit=null" title="关闭"><X :size="20"/></button></header><div class="drawer-body"><p class="muted small">历史记录保留当时的价格与规格；修正来源后可预览并重算选定记录。</p><pre class="json-detail sensitive">{{JSON.stringify(inspecting||audit,null,2)}}</pre></div></section></div><RecalculateDialog v-if="recalcRow" :collection="selectedCollection" :source-id="recalcRow.id" @close="recalcRow=null" @saved="recalcRow=null;emit('changed');emit('notify','已按预览重算历史记录。')"/></div></template>
